UPDATE companies SET description='Lusk Scandia Woodworks is based in Coon Valley, Wisconsin. Mike Lusk began working with wood in 1985, and by 2000 the craft became a full-time profession. The business is owned and operated by Mike and Becky Lusk, a husband-and-wife team who create custom handcrafted Scandinavian-inspired wood pieces.

The shop produces a range of items including custom cabinets, doors, shelves, tables, trunks, bowls, Scandinavian ships, ornaments, figurines, and plaques. Most pieces are handcrafted from basswood (often left unfinished for customer rosemaling or painting) and various hardwoods for stained finishes. Mike Lusk handles the woodcarving, drawing on traditional Norwegian designs studied at the Vesterheim Norwegian-American Museum, where he earned a gold medal in 1992 and now teaches carving classes.

Testimonials mention customers from Wisconsin, Texas, and elsewhere purchasing mirrors, trays, bowls, and ornaments. The company also serves woodcarving students through classes at Vesterheim Museum, Norskedalen Heritage Center, and local clubs.

The Lusks emphasize Scandinavian design principles—well-made, beautifully designed, built to last—and highlight the personal, one-of-a-kind nature of each handmade piece. Mike’s family heritage (his grandfather a Norwegian immigrant woodcarver, his mother a Vesterheim Gold-medalist in rosemaling) informs the aesthetic and techniques.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom cabinetry", "Hand-carved wooden bowls", "Scandinavian-style furniture (tables, shelves, trunks)", "Wooden ornaments and figurines", "Woodcarving classes (figure, ale bowl, dragonstil)", "Custom design from traditional patterns", "Basswood pieces for rosemaling/painting", "Hardwood pieces for staining"], "industries": [], "materials": ["Basswood", "Hardwoods"], "equipment": [], "volume": "", "lead_time": "10-16 weeks", "tolerances": "", "built_on": ["Handmade, one-of-a-kind Scandinavian-inspired wood pieces", "Basswood and hardwood options for customer finishing", "Gold-medal woodcarving expertise with teaching at Vesterheim Museum", "Ships to all 50 states with 10-16 week lead time", "Previous catalog items remain available"], "facts_used": ["Founded 1985 -> db", "Location Coon Valley, WI -> db", "Owners Mike and Becky Lusk -> /", "Products: custom cabinets, doors, shelves, tables, trunks, bowls, ships, ornaments, figurines, plaques -> /", "Materials: basswood, hardwoods -> /", "Lead time 10-16 weeks -> /", "Ships to all 50 states -> /", "Teaches woodcarving at Vesterheim Museum, Norskedalen Heritage Center -> /", "Gold medal 1992 Vesterheim -> /", "Scandinavian design inspiration -> /", "Family heritage: grandfather Hans Simonson, mother Jean Giese -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Together we make a variety of finely hand crafted Scandinavian inspired wood pieces.", "founded_year": "1985", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='lusk-scandia-woodworks' AND approved AND profile IS NULL;
